page_data_script:
if frappe.session.user == "Guest":
    redirect("/cafe/login")

if frappe.db.exists("Cafe User", frappe.session.user):
    handle = frappe.db.get_value("Cafe User", frappe.session.user, "handle")
    redirect(f"/cafe/profile/{handle}")

breadcrumbs = [
    {"label": "Café", "url": "#"},
    {"label": "Onboarding", "url": "#"},
]

frappe_user = frappe.db.get_value(
    "User", frappe.session.user, ["full_name", "first_name", "last_name"], as_dict=1
)

data.page_data = {
    "breadcrumbs": breadcrumbs,
    "user": frappe.session.user,
    "user_data": frappe_user,
}
